 public override void _Draw(){DrawStyleBox(new StyleBoxFlat{BgColor=new(.055f,.085f,.085f),BorderColor=new(.25f,.31f,.27f),BorderWidthBottom=1,BorderWidthTop=1,BorderWidthLeft=1,BorderWidthRight=1,CornerRadiusTopLeft=8,CornerRadiusTopRight=8,CornerRadiusBottomLeft=8,CornerRadiusBottomRight=8},new Rect2(Vector2.Zero,Size));for(int i=0;i<5;i++){float x=74+i*143;var c=i<Bench?new Color(.53f,.71f,.43f):new Color(.34f,.40f,.36f);DrawLine(new(x,81),new(x,110),c,2,true);DrawLine(new(x,110),new(x-4,103),c,2,true);DrawLine(new(x,110),new(x+4,103),c,2,true);DrawLine(new(x,177),new(x,191),c,2,true);if(i<4){float end=x+76;DrawLine(new(x+67,145),new(end,145),c,2,true);DrawLine(new(end,145),new(end-4,141),c,2,true);DrawLine(new(end,145),new(end-4,149),c,2,true);}}}
